def get_desc(path):
    if "/src/statspai/synth/" in path:
        return "新增合成控制法 (Synthetic Control) 相关模块及功能"
    elif "/src/statspai/target_trial/" in path:
        return "新增目标试验模拟 (Target Trial Emulation) 相关模块及功能"
    elif "/src/statspai/timeseries/" in path:
        return "新增时间序列分析 (Time Series) 相关模块及功能"
    elif "/src/statspai/tmle/" in path:
        return "新增目标最大似然估计 (TMLE) 相关模块及功能"
    elif "/src/statspai/transport/" in path:
        return "新增可移植性与泛化性 (Transportability & Generalizability) 相关模块及功能"
    elif "/src/statspai/utils/" in path:
        return "新增工具类及数据生成过程 (DGP) 等辅助功能"
    elif "/src/statspai/workflow/" in path:
        return "新增因果推断工作流 (Causal Workflow) 及报告生成功能"
    elif "/tests/" in path:
        return "新增对应的单元测试和集成测试文件，以提高代码覆盖率并验证新功能的正确性"
    else:
        return "新增文件以支持新功能"

out = "此次合并主要引入了大量因果推断与统计建模的新模块，包括合成控制法、目标试验模拟、时间序列分析、目标最大似然估计（TMLE）以及相关的测试用例。这些变更显著扩展了框架的分析能力，并增强了工具类的支持和工作流集的完整性。\n"
out += "| 文件 | 变更 |\n"
out += "|------|---------|\n"

for item in data:
    path = item["path"].replace("/workspace/StatsPAI/", "")
    desc = get_desc(item["path"])
    out += f"| {path} | - {desc} |\n"

with open("report.md", "w") as f:
    f.write(out)

